      if (f) { if (rng.next() < 0.4) wrapper(); else if (rng.next() < 0.6) gown(rng.pick(SHIRTS)); } else if (WHITE_COLLAR.has(p.job)) look.sleeves = rng.next() < 0.6 ? 'long' : 'short';
