      for (let i = 0; i < legs.length - 1; i += 1) strut(B, [legs[i] * W, b * 0.45, -1.3 - (i % 2 ? 0.8 : 0)], [legs[i + 1] * W, b * 0.45, -1.3 - ((i + 1) % 2 ? 0.8 : 0)], 0.08, c.steel, 6);
