      for (let y = 0.6, k = 0; y < top - 0.5; y += 1.2, k += 1) { for (const dz of [-0.45, 0.45]) strut(B, [mx - 0.45, y, -1.2 + dz], [mx + 0.45, y + 1.2, -1.2 + dz], 0.04, c.steel, 5); B.box(0.9, 0.08, 0.9, at(mx, y, -1.2), c.steel); }
