  for (let i = 0; i < data.length; i += 1) {
    seed = (seed * 16807) % 2147483647;
    const white = seed / 1073741823.5 - 1;
    if (colour === 'brown') { last = (last + 0.02 * white) / 1.02; data[i] = last * 3.2; } else data[i] = white;
  }
