  const playing = [];               // short sounds now sounding: { kind, until }
  const ear = { x: 0, z: 0 };
  const PEER_HEARD = 120, PEER_ENGINES = 3;   // another player's motorcycle is heard within this many metres; the nearest few
  const ducks = { panel: false, focusUntil: 0 };
