      const seethe = looped(nodes.brown, 'lowpass', 380, 0.9), hiss = looped(nodes.white, 'bandpass', 4200, 0.6);
      seethe.gain.connect(p); hiss.gain.connect(p); p.connect(nodes.ambient);
