        animateCharacter(actor, dt, moving ? Math.max(0.7, Math.min(2.2, stride / Math.max(dt, 0.001))) : 0, working);
        showName(actor, toPlayer < 8 && Math.hypot(camera.position.x - g.position.x, camera.position.z - g.position.z) > 3.2, dt);
